// UCLN của a, b
int mn = a < b ? a : b;
for(int i = mn; i >= 1; i--){
    if(a % i == 0 && b % i == 0){
        printf("%d", i); break;
    }
}

// chữ số chẵn đầu tiên từ phải sang của n
while(n != 0){
    if(n % 2 == 0){ printf("%d", n % 10); break; }
    n /= 10;
}

